using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace EnumExtensions.Tool.Helpers;

internal static class AttributeExtensions
{
    public static void EnsureAttributeExists(string directory)
    {
        var attrPath = Path.Combine(directory, "GenerateEnumExtensionsAttribute.g.cs");

        if (File.Exists(attrPath))
            return;

        // internal : chaque projet embarque sa propre copie sans conflit de type
        // entre assemblies (même approche que les source generators).
        var code = """
// <auto-generated/>
using System;

[AttributeUsage(AttributeTargets.Enum)]
internal sealed class GenerateEnumExtensionsAttribute : Attribute
{
}
""";

        File.WriteAllText(attrPath, code);
    }

    internal static bool HasGenerateAttribute(EnumDeclarationSyntax enumDecl)
    {
        foreach (var attrList in enumDecl.AttributeLists)
        {
            foreach (var attr in attrList.Attributes)
            {
                if (attr.Name is IdentifierNameSyntax ins &&
                     (ins.Identifier.Text is "GenerateEnumExtensions" or "GenerateEnumExtensionsAttribute"))
                    return true;
            }
        }

        return false;
    }
}
